"""Editorial ENTENDA rows for CC-10, arts. 973-1040.

O art. 980-A, integralmente revogado pela Lei 14.382/2022, não integra ROWS.
"""
from __future__ import annotations


def row(says, means, example, warning, term, definition):
    return {"target": None, "o_que_diz": says, "o_que_significa": means, "exemplo_pratico": example, "atencao": warning, "palavras_dificeis": [{"termo": term, "explicacao": definition}]}


ROWS = {
    "973": row("Quem exerce atividade empresarial apesar de impedimento legal responde pelas obrigações que contrair.", "A proibição não permite ao impedido escapar das dívidas do negócio irregular; ele continua obrigado perante credores.", "Servidor legalmente impedido explora comércio e responde pelos contratos celebrados.", "O artigo não torna lícita a atividade nem afasta outras sanções do impedimento.", "Impedimento legal", "proibição estabelecida em lei para exercer atividade própria de empresário"),
    "974": row("O incapaz pode continuar empresa que já exercia quando capaz, que recebeu dos pais ou que herdou, por representante ou com assistência. Exige autorização judicial, revogável sem prejudicar terceiros; bens anteriores estranhos à empresa ficam protegidos se constarem do alvará. Sociedade com sócio incapaz deve ter capital integralizado, impedir sua administração e assegurar representação ou assistência adequada.", "A lei admite continuidade controlada, não o início livre de empresa pelo incapaz, e cria salvaguardas pessoais, patrimoniais e registrais.", "Menor herda estabelecimento; o juiz avalia riscos, autoriza a continuidade e identifica no alvará seus bens particulares protegidos.", "Representante atua pelo absolutamente incapaz; assistente acompanha o relativamente incapaz. Os três requisitos societários do § 3º são cumulativos.", "Alvará", "decisão judicial formal que concede a autorização prevista na lei"),
    "975": row("Se o representante ou assistente também estiver legalmente impedido de ser empresário, deverá nomear um ou mais gerentes com aprovação judicial. O juiz também pode exigir gerente por conveniência, sem liberar representante ou assistente da responsabilidade pelos atos dele.", "A gestão profissional substitutiva preserva a empresa do incapaz, mas quem o representa continua obrigado a fiscalizar.", "Tutor impedido indica gerente, obtém aprovação do juiz e permanece responsável por falhas de supervisão.", "A aprovação judicial do nome não transfere integralmente a responsabilidade ao gerente.", "Gerente", "pessoa designada para conduzir a empresa em lugar do representante ou assistente impedido"),
    "976": row("A emancipação, a autorização para o incapaz continuar a empresa e eventual revogação devem ser inscritas ou averbadas no registro empresarial. A firma será usada pelo gerente, representante ou pelo próprio incapaz quando autorizado.", "A publicidade registral permite que terceiros saibam quem pode atuar e se a autorização continua válida.", "Revogada a autorização judicial, a Junta Comercial averba o fato para torná-lo publicamente cognoscível.", "Inscrição e averbação têm funções registrais distintas; deve-se registrar também a revogação.", "Averbação", "anotação no registro que atualiza ou complementa informação já inscrita"),
    "977": row("Cônjuges podem formar sociedade entre si ou com terceiros, exceto se casados em comunhão universal ou separação obrigatória de bens.", "A liberdade societária conjugal é limitada nos dois regimes expressamente indicados para preservar suas regras patrimoniais.", "Casados em comunhão parcial podem ser sócios, mas casal em comunhão universal não pode contratar a sociedade prevista.", "A vedação depende do regime matrimonial vigente e não deve ser ampliada a regimes não mencionados.", "Separação obrigatória", "regime de bens imposto pela lei em situações determinadas"),
    "978": row("O empresário casado pode alienar ou gravar com direito real os imóveis integrantes do patrimônio da empresa sem autorização do cônjuge, qualquer que seja o regime de bens.", "A norma facilita a circulação dos ativos empresariais e excepciona a exigência conjugal para esses imóveis.", "Empresário oferece imóvel da empresa em hipoteca sem colher assinatura do cônjuge.", "É necessário demonstrar que o imóvel integra o patrimônio empresarial; a regra não abrange automaticamente bens particulares estranhos à empresa.", "Outorga conjugal", "consentimento do cônjuge exigido para certos atos patrimoniais"),
    "979": row("Pactos antenupciais do empresário e títulos de doação, herança ou legado com cláusulas de incomunicabilidade ou inalienabilidade devem ser arquivados e averbados também no registro empresarial, além do Registro Civil.", "A dupla publicidade informa credores e parceiros sobre limites ao patrimônio do empresário.", "Empresário recebe imóvel hereditário inalienável e leva o título à Junta Comercial.", "O registro empresarial não substitui o Registro Civil indicado pela lei.", "Incomunicabilidade", "cláusula que impede o bem de integrar o patrimônio comum do casal"),
    "980": row("A separação judicial do empresário, sua homologação e a reconciliação só podem ser opostas a terceiros depois de arquivadas e averbadas no registro empresarial.", "Entre os envolvidos o ato pode existir antes, mas sua eficácia contra terceiros depende da publicidade registral.", "Empresário reconciliado não invoca o fato contra credor anterior à averbação empresarial.", "O artigo exige tanto o arquivamento quanto a averbação antes da oponibilidade.", "Oponibilidade", "aptidão de um ato para produzir efeitos contra terceiros"),
    "981": row("Sociedade nasce do contrato pelo qual pessoas se obrigam reciprocamente a contribuir com bens ou serviços para atividade econômica e dividir os resultados. A atividade pode limitar-se a um ou mais negócios determinados.", "Contribuição, atividade econômica comum e partilha de resultados formam o núcleo do contrato de sociedade.", "Duas pessoas aportam capital e trabalho para realizar e repartir o resultado de um empreendimento específico.", "A forma de divisão e o tipo societário devem respeitar as demais regras legais; mera cooperação não é sempre sociedade.", "Contrato de sociedade", "acordo destinado a reunir contribuições para atividade econômica e partilha de resultados"),
    "982": row("Em regra, é empresária a sociedade que exerce atividade própria de empresário sujeito a registro; as demais são simples. Sociedade por ações é sempre empresária e cooperativa é sempre simples, qualquer que seja o objeto.", "A natureza decorre do modo e objeto da atividade, com duas classificações legais obrigatórias.", "Cooperativa que atua em mercado economicamente organizado continua classificada como sociedade simples.", "Sociedade simples não significa ausência de atividade econômica; e sociedade empresária não se confunde com empresário individual.", "Sociedade simples", "sociedade que não é empresária segundo os critérios legais"),
    "983": row("A sociedade empresária deve adotar um tipo regulado nos arts. 1.039 a 1.092. A simples pode escolher um deles ou seguir suas normas próprias, respeitadas as regras de conta de participação, cooperativa e leis especiais que imponham tipo específico.", "O tipo societário organiza responsabilidade, administração e funcionamento, mas certas atividades recebem disciplina especial.", "Sociedade simples escolhe o tipo limitada; instituição sujeita a lei especial adota o tipo exigido por essa lei.", "A liberdade de escolha não supera imposições legais setoriais nem as exceções expressas.", "Tipo societário", "modelo jurídico previsto em lei para organizar uma sociedade"),
    "984": row("Sociedade de atividade rural constituída ou transformada segundo tipo empresarial pode registrar-se na Junta Comercial e, depois da inscrição, equipara-se à sociedade empresária. O pedido observa, quando cabível, as regras de transformação.", "Para a sociedade rural, a equiparação depende de opção formal e só produz efeitos após o registro.", "Produtores organizados como limitada rural pedem inscrição e passam ao regime de sociedade empresária.", "A atividade rural, sozinha, não gera a equiparação; forma adequada e inscrição são indispensáveis.", "Equiparação", "atribuição dos mesmos efeitos jurídicos a situações diferentes por determinação legal"),
    "985": row("A sociedade adquire personalidade jurídica quando seus atos constitutivos são inscritos no registro próprio, na forma da lei.", "O registro separa juridicamente a sociedade das pessoas dos sócios e marca o nascimento da pessoa jurídica.", "Contrato de sociedade simples é inscrito no registro competente e a sociedade passa a titularizar direitos próprios.", "Antes do registro podem incidir as regras da sociedade não personificada; assinar o contrato, por si só, não basta.", "Personalidade jurídica", "aptidão de uma entidade para ser sujeito autônomo de direitos e obrigações"),
    "986": row("Enquanto os atos constitutivos não forem inscritos, a sociedade, salvo a sociedade por ações em organização, rege-se pelas normas da sociedade em comum e, subsidiariamente, pelas regras compatíveis da sociedade simples.", "A falta de registro não apaga a relação societária, mas impõe regime não personificado e maior exposição dos sócios.", "Sócios começam a operar antes da inscrição e ficam sujeitos às regras da sociedade em comum.", "A aplicação subsidiária exige compatibilidade, e a exceção das sociedades por ações possui regime próprio.", "Sociedade em comum", "sociedade não personificada cujos atos constitutivos ainda não foram inscritos"),
    "987": row("Entre si ou perante terceiros, os sócios somente provam a sociedade em comum por escrito; terceiros podem demonstrá-la por qualquer meio admitido.", "A lei impõe prova mais rigorosa aos sócios, mas protege quem negociou externamente sem acesso ao contrato.", "Fornecedor comprova por mensagens e testemunhas que negociou com sociedade não registrada; sócio precisa de documento escrito.", "A assimetria é intencional: a liberdade probatória pertence ao terceiro, não aos sócios.", "Prova escrita", "documento capaz de demonstrar a existência da relação societária"),
    "988": row("Bens e dívidas sociais formam patrimônio especial pertencente em comum aos sócios.", "Mesmo sem personalidade jurídica, há uma massa patrimonial vinculada à atividade social.", "Máquinas aportadas e dívida de fornecedor integram o patrimônio especial da sociedade em comum.", "Titularidade comum não elimina a responsabilidade pessoal prevista nos artigos seguintes.", "Patrimônio especial", "conjunto de bens e obrigações separado por sua destinação jurídica"),
    "989": row("Os bens sociais respondem pelos atos de gestão de qualquer sócio, salvo limitação expressa de poderes conhecida ou que devesse ser conhecida pelo terceiro.", "Internamente pode haver restrição, mas ela só protege o patrimônio social contra terceiro informado ou negligente quanto à restrição.", "Contrato limita compras de um sócio e fornecedor comprovadamente conhece a cláusula.", "Pacto oculto não prejudica terceiro de boa-fé; cabe demonstrar seu conhecimento real ou exigível.", "Limitação de poderes", "restrição contratual à autoridade de gestão de um sócio"),
    "990": row("Todos os sócios da sociedade em comum respondem solidária e ilimitadamente pelas dívidas sociais; quem contratou em nome dela não tem o benefício de exigir primeiro a execução dos bens sociais.", "Credores contam com todo o patrimônio dos sócios, e o sócio contratante tem exposição ainda mais imediata.", "Fornecedor cobra a dívida integral de um sócio, especialmente daquele que celebrou a compra.", "Solidariedade permite cobrança integral, mas preserva eventual acerto regressivo interno; benefício de ordem não vale para o contratante.", "Responsabilidade ilimitada", "responsabilidade que pode alcançar bens pessoais além do valor investido"),
    "991": row("Na sociedade em conta de participação, apenas o sócio ostensivo exerce a atividade em nome próprio e sob responsabilidade exclusiva perante terceiros; os participantes compartilham resultados e se obrigam apenas perante ele conforme o contrato.", "A relação externa concentra-se no ostensivo, enquanto os participantes mantêm vínculo interno.", "Investidor participante aporta recursos, mas contratos com clientes são celebrados somente pelo ostensivo.", "O participante que intervém externamente pode sofrer a responsabilidade prevista no art. 993.", "Sócio ostensivo", "sócio que atua publicamente, em nome próprio, na conta de participação"),
    "992": row("A sociedade em conta de participação independe de forma específica e pode ser provada por todos os meios jurídicos admitidos.", "Sua constituição é informal, sem solenidade ou registro constitutivo obrigatório.", "Partes comprovam a sociedade por contrato, transferências e mensagens coerentes.", "Liberdade de forma não dispensa prova dos elementos do vínculo nem exigências próprias de atos específicos.", "Liberdade de forma", "possibilidade de constituir negócio sem solenidade determinada"),
    "993": row("O contrato da conta de participação produz efeitos apenas entre os sócios, e seu registro não cria personalidade jurídica. O participante pode fiscalizar, mas, se intervier nas relações do ostensivo com terceiros, responde solidariamente pelas obrigações em que intervier.", "A estrutura permanece interna mesmo registrada; atuação externa do participante rompe a separação quanto ao negócio concreto.", "Participante negocia diretamente contrato do ostensivo e passa a responder solidariamente por ele.", "Fiscalizar não é intervir. A solidariedade limita-se às obrigações nas quais houve intervenção.", "Sócio participante", "sócio interno que contribui e participa dos resultados sem atuar perante terceiros"),
    "994": row("Contribuições do participante e do ostensivo formam patrimônio especial da conta, eficaz somente entre eles. A falência do ostensivo dissolve a sociedade e o saldo vira crédito quirografário; a falência do participante submete o contrato às regras dos contratos bilaterais do falido.", "A separação patrimonial é interna e o tratamento falimentar varia conforme qual sócio quebra.", "Falido o ostensivo, liquida-se a conta e eventual saldo do participante concorre sem garantia especial.", "O patrimônio especial não é pessoa jurídica nem blindagem contra terceiros do ostensivo.", "Crédito quirografário", "crédito sem garantia real ou preferência especial"),
    "995": row("Salvo cláusula diferente, o sócio ostensivo só pode admitir novo sócio com consentimento expresso dos demais.", "A composição pessoal da conta de participação é protegida, embora o contrato possa disciplinar de outro modo.", "Ostensivo pretende admitir novo investidor e obtém concordância escrita dos participantes.", "Silêncio não equivale automaticamente a consentimento expresso.", "Consentimento expresso", "concordância manifestada de modo claro e inequívoco"),
    "996": row("As regras da sociedade simples aplicam-se subsidiariamente à conta de participação quando compatíveis; a liquidação segue a prestação de contas processual. Havendo vários ostensivos, suas contas são julgadas no mesmo processo.", "A norma preenche lacunas sem descaracterizar a estrutura interna e centraliza a apuração das contas.", "Encerrada a operação, participante pede prestação de contas dos dois sócios ostensivos no mesmo processo.", "A remissão é subsidiária e condicionada à compatibilidade, não aplicação integral automática.", "Aplicação subsidiária", "uso de outro regime para preencher lacunas de maneira compatível"),
    "997": row("A sociedade simples constitui-se por contrato escrito, público ou particular, que identifique sócios, denominação, objeto, sede, prazo, capital, quotas e sua realização, contribuições em serviços, administradores e poderes, participação em resultados e eventual responsabilidade subsidiária. Pacto separado contrário ao instrumento é ineficaz perante terceiros.", "O contrato deve tornar transparentes os elementos essenciais de organização, patrimônio e responsabilidade.", "Três profissionais registram contrato com capital, quotas, administrador, divisão de lucros e extensão da responsabilidade.", "A omissão de cláusula obrigatória pode impedir o registro; acordo paralelo não pode reduzir a proteção de terceiros.", "Ato constitutivo", "instrumento que cria e organiza juridicamente a sociedade"),
    "998": row("A sociedade simples deve pedir inscrição do contrato no Registro Civil das Pessoas Jurídicas de sua sede em trinta dias da constituição, juntando contrato autenticado, procuração e autorização quando cabíveis. A inscrição recebe termo e número contínuo no livro próprio.", "O procedimento dá publicidade, regularidade e personalidade à sociedade.", "Sociedade constituída em 1º de março protocola até o prazo legal o contrato e a procuração do sócio representado.", "O prazo não dispensa documentos nem o registro competente da sede.", "Inscrição", "assento inicial do ato constitutivo no registro público competente"),
    "999": row("Mudanças nas matérias essenciais listadas no art. 997 exigem consentimento de todos os sócios; outras podem ser aprovadas por maioria absoluta, salvo cláusula de unanimidade. Toda alteração deve ser averbada com as formalidades registrais.", "Alterações estruturais recebem quórum máximo, enquanto matérias não essenciais admitem decisão majoritária.", "Mudança do objeto social exige unanimidade; outra questão não essencial pode ser aprovada por maioria absoluta.", "É preciso classificar corretamente a matéria e observar quórum contratual mais exigente, além da averbação.", "Maioria absoluta", "votos superiores à metade da base legal de cálculo"),
    "1000": row("Sociedade simples que criar sucursal, filial ou agência em outra circunscrição deve inscrevê-la no registro local, comprovando a inscrição da sede, e averbar sua criação no registro da sede.", "A unidade secundária exige publicidade tanto onde opera quanto no registro originário.", "Sociedade abre filial em outra cidade, registra-a ali e averba a abertura na sede.", "As duas providências são cumulativas, mesmo que a unidade não tenha personalidade própria.", "Sucursal", "estabelecimento secundário ligado à mesma pessoa jurídica"),
    "1001": row("As obrigações dos sócios começam com o contrato, salvo data diferente nele prevista, e terminam apenas após a liquidação e a extinção das responsabilidades sociais.", "Entrada e saída formal não eliminam imediatamente deveres ligados à vida e ao encerramento da sociedade.", "Contrato assinado hoje produz dever de aporte desde hoje, embora a operação comece depois.", "O fim das atividades não basta: liquidação e responsabilidades remanescentes precisam ser encerradas.", "Liquidação", "processo de apurar ativos, pagar dívidas e distribuir o saldo da sociedade"),
    "1002": row("Sócio não pode colocar outra pessoa em seu lugar no exercício de suas funções sem consentimento dos demais formalizado em alteração contratual.", "As funções societárias têm caráter pessoal e sua substituição muda a organização pactuada.", "Sócio prestador de serviços só indica substituto após aprovação e modificação do contrato.", "Delegação pontual permitida não se confunde necessariamente com substituição integral da posição funcional.", "Modificação contratual", "alteração formal do contrato social aprovada pelo quórum exigido"),
    "1003": row("Cessão total ou parcial de quota sem modificação contratual consentida pelos demais não produz efeitos contra sociedade e sócios. Por dois anos após a averbação, cedente e cessionário respondem solidariamente pelas obrigações que o cedente tinha como sócio.", "A transferência exige integração formal ao contrato e mantém garantia temporária pelas obrigações anteriores.", "Sócio cede sua quota; após consentimento e averbação, ainda responde por dois anos junto com o adquirente.", "O prazo começa na averbação e a solidariedade abrange obrigações ligadas à condição anterior do cedente.", "Cessão de quota", "transferência da participação societária a outra pessoa"),
    "1004": row("Sócio deve realizar a contribuição na forma e prazo contratados. Notificado e ainda inadimplente por trinta dias, responde pelo dano da mora; a maioria dos demais pode preferir excluí-lo ou reduzir sua quota ao valor realizado, observada a regra legal de liquidação.", "O sócio remisso recebe oportunidade formal para cumprir, seguida de alternativas destinadas a proteger a sociedade.", "Sócio não integraliza capital, ignora notificação por trinta dias e tem a quota reduzida pela maioria.", "Exclusão ou redução não é automática: exige mora após notificação e decisão dos demais nos termos legais.", "Sócio remisso", "sócio que não realiza a contribuição assumida no contrato"),
    "1005": row("Sócio que aporta domínio, posse ou uso de bem responde pela evicção; quem aporta crédito responde pela solvência do devedor.", "O aporte deve entregar utilidade patrimonial efetiva, e o sócio suporta riscos jurídicos específicos do bem ou crédito transferido.", "Crédito aportado é incobrável por insolvência do devedor e o sócio transferente responde perante a sociedade.", "Evicção e insolvência são riscos distintos e dependem do objeto aportado.", "Evicção", "perda do bem em razão de direito anterior reconhecido a terceiro"),
    "1006": row("Sócio cuja contribuição é prestar serviços não pode trabalhar em atividade estranha à sociedade, salvo convenção contrária, sob pena de perder lucros e ser excluído.", "A regra protege a dedicação prometida pelo sócio de serviço, mas admite autorização contratual diferente.", "Sócio contratado para prestar trabalho exclusivo assume emprego externo sem permissão e pode sofrer as sanções.", "Privação de lucros e exclusão exigem o enquadramento legal; atividade autorizada não viola a regra.", "Sócio de serviço", "sócio cuja contribuição consiste em trabalho, e não em bens ou dinheiro"),
    "1007": row("Salvo ajuste diferente, cada sócio participa de lucros e perdas proporcionalmente às quotas; o sócio de serviços participa dos lucros pela média do valor das quotas.", "A lei fornece critério supletivo de repartição quando o contrato não estabelecer outro válido.", "Sócios de capital dividem resultado conforme suas quotas e o prestador de serviços usa a média prevista.", "O contrato pode ajustar a participação, mas não excluir sócio integralmente dos resultados conforme o art. 1.008.", "Regra supletiva", "regra legal aplicável quando as partes não dispõem validamente de outro modo"),
    "1008": row("É nula a cláusula que exclui qualquer sócio da participação nos lucros e nas perdas.", "O pacto leonino não produz efeito porque compartilhar resultados positivos e negativos integra a essência societária.", "Contrato que assegura todos os lucros a um sócio e só perdas a outro contém cláusula nula.", "A nulidade da estipulação deve ser distinguida de repartição desigual, que pode ser válida se não houver exclusão total.", "Pacto leonino", "cláusula que afasta sócio de lucros ou de perdas"),
    "1009": row("Administradores que distribuem lucros ilícitos ou fictícios respondem solidariamente; sócios que os recebem também respondem se sabiam ou deveriam saber da ilegitimidade.", "A norma protege o patrimônio social e credores contra distribuição sem resultado real ou contrária à lei.", "Administrador distribui lucro inexistente e sócio informado o recebe; ambos respondem pela recomposição.", "Para o sócio recebedor, a lei exige conhecimento efetivo ou que fosse razoavelmente exigível; a responsabilidade dos administradores decorre da distribuição.", "Lucro fictício", "valor apresentado como lucro sem corresponder a resultado efetivamente apurado"),
    "1010": row("Deliberações dos sócios são tomadas por votos calculados conforme o valor das quotas. Maioria absoluta exige mais da metade do capital; no empate vence a posição apoiada por mais sócios e, persistindo, decide o juiz. Sócio com interesse contrário responde se seu voto aprovar operação danosa.", "Poder de voto acompanha capital, com critérios sucessivos de desempate e responsabilização por conflito de interesses decisivo.", "Duas propostas empatam em capital; prevalece a que tiver mais sócios apoiadores.", "O conflito gera perdas e danos quando o voto do interessado foi determinante para aprovar a operação.", "Conflito de interesses", "oposição entre o interesse pessoal do sócio e o interesse da sociedade"),
    "1011": row("Administrador deve agir com cuidado e diligência de pessoa ativa e proba. Impedidos por lei especial e condenados pelos crimes enumerados não podem administrar enquanto durarem os efeitos da condenação; aplicam-se, quando cabíveis, regras do mandato.", "A administração exige padrão objetivo de lealdade e cuidado e idoneidade jurídica mínima.", "Administrador avalia riscos e documenta decisão como faria pessoa prudente com patrimônio próprio.", "A lista de impedimentos deve ser conferida com leis especiais e com a duração concreta dos efeitos da condenação.", "Dever de diligência", "obrigação de administrar com cuidado, competência e honestidade"),
    "1012": row("Administrador nomeado em instrumento separado deve averbar a nomeação no registro; pelos atos anteriores ao pedido de averbação responde pessoal e solidariamente com a sociedade.", "A falta de publicidade não impede atuação, mas aumenta a responsabilidade do administrador no período irregular.", "Nomeado fora do contrato, administrador celebra compra antes de pedir averbação e responde junto com a sociedade.", "A responsabilidade alcança atos praticados antes do requerimento, não apenas antes da conclusão do registro.", "Instrumento separado", "documento de nomeação distinto do contrato social"),
    "1013": row("Se o contrato nada disser, cada sócio administra separadamente. Um administrador pode impugnar operação de outro, submetendo-a à maioria; quem age sabendo ou devendo saber que contraria a maioria responde pelos danos.", "A administração disjuntiva permite ação individual, mas cria controle interno e responsabilidade por desrespeito deliberado à decisão coletiva.", "Administrador contesta compra pretendida por outro e os sócios decidem por maioria não realizá-la.", "A impugnação deve anteceder a operação útil; agir contra a maioria exige culpa cognoscível e dano para indenização.", "Administração disjuntiva", "modelo em que cada administrador pode atuar separadamente"),
    "1014": row("Quando a administração é conjunta, todos os administradores devem participar do ato, salvo urgência em que omissão ou demora possa causar dano grave ou irreparável.", "A atuação isolada é excepcional e serve apenas para proteger a sociedade diante de perigo urgente.", "Um administrador sozinho adota medida imediata para impedir perda definitiva de bem social.", "Conveniência ou rapidez comum não bastam; deve existir urgência e risco grave ou irreparável.", "Administração conjunta", "modelo em que o ato exige a participação de todos os administradores competentes"),
    "1015": row("Sem restrição contratual, administradores podem praticar atos pertinentes à gestão. Para onerar ou vender imóvel fora do objeto social, é necessária decisão da maioria dos sócios. O antigo parágrafo único foi revogado.", "Os poderes gerais cobrem a atividade social; negócios imobiliários estranhos ao objeto recebem controle dos sócios.", "Empresa cujo objeto não envolve imóveis só vende prédio após aprovação da maioria.", "Não se deve aplicar o parágrafo revogado nem exigir a deliberação quando o ato integra regularmente o objeto social.", "Ônus real", "direito ou garantia que grava diretamente um bem, como hipoteca"),
    "1016": row("Administradores respondem solidariamente perante a sociedade e terceiros prejudicados pelos danos causados por culpa no exercício de suas funções.", "Havendo atuação culposa, dano e nexo, os administradores responsáveis podem ser cobrados integralmente.", "Dois administradores negligenciam dever comum e causam prejuízo a fornecedor e à sociedade.", "O artigo exige culpa no desempenho; a solidariedade não transforma todo insucesso empresarial em responsabilidade automática.", "Responsabilidade solidária", "possibilidade de cobrar de qualquer responsável o total devido"),
    "1017": row("Administrador que usa crédito ou bem social em benefício próprio ou alheio sem consentimento escrito deve restituir ou pagar o equivalente, entregar os lucros obtidos e indenizar prejuízos. Também sofre sanções se participa de deliberação em operação com interesse contrário.", "A norma combate apropriação e conflito de interesses, recompondo integralmente o patrimônio social.", "Administrador usa dinheiro da sociedade em negócio pessoal e devolve capital, lucros e perdas causadas.", "Consentimento deve ser escrito; restituição de ganhos não elimina indenização por prejuízo adicional.", "Dever de lealdade", "obrigação de priorizar o interesse da sociedade e não se apropriar de oportunidades ou bens sociais"),
    "1018": row("Administrador não pode transferir a outra pessoa o próprio cargo, mas pode constituir mandatários da sociedade dentro de seus poderes, especificando no instrumento os atos autorizados.", "Delegar atos delimitados é permitido; substituir-se integralmente na função administrativa não é.", "Administrador concede procuração para mandatário assinar contrato específico em nome da sociedade.", "Procuração genérica que esvazie o cargo pode caracterizar substituição vedada.", "Mandatário", "pessoa autorizada por procuração a praticar atos determinados em nome de outra"),
    "1019": row("Poderes do sócio nomeado administrador em cláusula expressa do contrato são irrevogáveis, salvo justa causa reconhecida judicialmente a pedido de sócio. Poderes dados por ato separado ou a não sócio podem ser revogados a qualquer tempo.", "A estabilidade varia conforme a origem e a pessoa da nomeação, protegendo a administração contratualmente pactuada.", "Sócio administrador nomeado no contrato só é removido por justa causa judicialmente reconhecida.", "Irrevogabilidade não é absoluta; exige cláusula contratual expressa e cede diante de justa causa.", "Justa causa", "motivo grave juridicamente suficiente para afastar o administrador"),
    "1020": row("Administradores devem prestar contas justificadas aos sócios e apresentar anualmente inventário, balanço patrimonial e balanço de resultado econômico.", "Transparência e periodicidade permitem fiscalizar gestão, patrimônio e desempenho.", "Ao fim do exercício, administrador entrega documentos contábeis e explica despesas relevantes.", "Apresentar números sem documentos ou justificativas pode não cumprir o dever de prestar contas.", "Balanço patrimonial", "demonstração da posição de bens, direitos, obrigações e patrimônio líquido"),
    "1021": row("Salvo época diferente prevista no contrato, o sócio pode examinar a qualquer tempo livros, documentos, caixa e carteira da sociedade.", "O direito de fiscalização é contínuo por padrão, embora o contrato possa organizar o momento do exame.", "Sócio solicita acesso a contratos, livros contábeis e posição de caixa para conferir a gestão.", "A fiscalização deve ser exercida de boa-fé e respeitar disciplina contratual válida, sem esvaziar o direito.", "Carteira", "conjunto de créditos, títulos e valores mantidos pela sociedade"),
    "1022": row("A sociedade exerce direitos, assume obrigações e atua em juízo por administradores com poderes especiais ou, na falta deles, por qualquer administrador.", "A representação orgânica permite que a pessoa jurídica aja externamente por quem administra.", "Administrador autorizado apresenta ação judicial e celebra contrato em nome da sociedade.", "Devem ser observados poderes especiais exigidos para o ato e limites constantes do contrato ou da lei.", "Representação orgânica", "atuação da pessoa jurídica por meio de seus órgãos de administração"),
    "1023": row("Se o patrimônio social não pagar as dívidas, os sócios respondem pelo saldo na proporção em que participam das perdas, salvo cláusula de solidariedade.", "A responsabilidade subsidiária é proporcional por padrão, podendo o contrato torná-la solidária.", "Falta cem mil reais após usar os bens sociais; sócios cobrem o saldo conforme sua participação nas perdas.", "Primeiro se verifica a insuficiência social e depois a regra contratual sobre proporção ou solidariedade.", "Saldo devedor", "parte da dívida que permanece após utilização do patrimônio responsável em primeiro lugar"),
    "1024": row("Bens particulares dos sócios só podem ser executados por dívida social depois de executados os bens da sociedade.", "A sociedade responde primariamente; o patrimônio pessoal tem proteção subsidiária.", "Credor busca primeiro ativos sociais antes de alcançar bem particular do sócio responsável.", "O benefício não significa irresponsabilidade, e pode ter exceções em regimes legais específicos.", "Benefício de ordem", "direito de exigir que o patrimônio principal seja executado antes do subsidiário"),
    "1025": row("Quem ingressa em sociedade já existente continua responsável pelas dívidas sociais anteriores à admissão.", "A entrada não cria corte temporal oponível aos credores da sociedade.", "Novo sócio ingressa hoje e pode responder, conforme o regime societário, por dívida social do ano anterior.", "A extensão patrimonial da responsabilidade depende do tipo e das demais regras aplicáveis; o artigo afasta apenas a exoneração temporal.", "Dívida anterior", "obrigação social constituída antes do ingresso do novo sócio"),
    "1026": row("Se outros bens do sócio devedor forem insuficientes, seu credor particular pode executar lucros ou a parte que lhe caberia na liquidação. Se a sociedade continuar, pode pedir liquidação da quota, cujo valor é apurado pelo art. 1.031 e depositado em dinheiro no juízo em até noventa dias.", "O credor pessoal alcança o valor econômico da participação sem tomar diretamente bens pertencentes à sociedade.", "Credor sem outros bens penhoráveis pede liquidação da quota do sócio e depósito judicial do valor.", "A medida pressupõe insuficiência patrimonial do devedor e segue forma, avaliação e prazo legais.", "Liquidação de quota", "apuração e conversão em dinheiro do valor da participação societária"),
    "1027": row("Herdeiros do cônjuge de sócio e cônjuge separado não podem exigir imediatamente a parte que lhes cabe na quota; participam da divisão periódica dos lucros até a liquidação da sociedade.", "A norma evita ingresso ou retirada forçada imediata e preserva a continuidade social, mantendo o interesse econômico.", "Ex-cônjuge recebe periodicamente parcela dos lucros, mas não exige de pronto o valor da quota.", "O direito econômico não equivale à condição de sócio nem autoriza interferência automática na gestão.", "Meação da quota", "parcela econômica da participação societária atribuível ao cônjuge"),
    "1028": row("Morto um sócio, sua quota é liquidada, salvo se o contrato dispuser de outro modo, os remanescentes escolherem dissolver a sociedade ou houver acordo com herdeiros para substituí-lo.", "A regra padrão é pagar o valor da participação, mas contrato e consenso podem preservar ou encerrar a sociedade.", "Herdeiros e sócios acordam que um sucessor ocupará a posição do falecido em vez de liquidar a quota.", "Herdeiro não se torna sócio automaticamente fora das hipóteses contratuais ou consensuais previstas.", "Resolução parcial", "encerramento do vínculo societário apenas em relação a um sócio"),
    "1029": row("Sócio pode retirar-se de sociedade por prazo indeterminado mediante aviso aos demais com sessenta dias; se o prazo for determinado, deve provar justa causa judicialmente. Nos trinta dias após o aviso, os demais podem optar pela dissolução.", "A saída voluntária é mais simples quando o vínculo não tem termo final e recebe contrapeso para planejamento dos remanescentes.", "Sócio notifica retirada em janeiro, respeita sessenta dias e os demais avaliam dissolução em trinta.", "Em sociedade com prazo determinado, simples vontade não substitui prova judicial de justa causa.", "Direito de retirada", "faculdade de encerrar a participação do sócio nas condições legais ou contratuais"),
    "1030": row("A maioria dos demais sócios pode pedir judicialmente a exclusão por falta grave ou incapacidade superveniente, ressalvado o regime do sócio remisso. Sócio falido ou cuja quota foi liquidada por credor é excluído de pleno direito.", "A exclusão judicial por conduta ou incapacidade difere das hipóteses automáticas previstas no parágrafo.", "Sócios majoritários ajuízam ação para excluir integrante que viola gravemente obrigações sociais.", "A maioria é calculada entre os demais e deve provar a causa; falência e liquidação da quota seguem exclusão legal automática.", "Exclusão de pleno direito", "afastamento que decorre diretamente da ocorrência prevista em lei"),
    "1031": row("Na resolução em relação a um sócio, sua quota integralizada é apurada pela situação patrimonial na data da resolução, em balanço especial, salvo contrato diverso. Reduz-se o capital se os demais não suprirem o valor, e o pagamento em dinheiro ocorre em noventa dias da liquidação, salvo ajuste diferente.", "A apuração busca retrato econômico contemporâneo da saída e disciplina seus efeitos sobre capital e pagamento.", "Sócio se retira; balanço especial calcula a quota e a sociedade paga em dinheiro dentro do prazo ajustável.", "Data da resolução, critério contratual válido e regras processuais aplicáveis devem ser verificados antes do cálculo.", "Balanço de determinação", "levantamento especial destinado a apurar o valor da participação na resolução societária"),
    "1032": row("Retirada, exclusão ou morte não eliminam a responsabilidade do ex-sócio ou herdeiros por obrigações anteriores durante dois anos após a averbação. Na retirada e exclusão, também há responsabilidade por obrigações posteriores, por igual período, enquanto a averbação não for pedida.", "A publicidade registral inicia o limite temporal e protege terceiros durante a transição.", "Ex-sócio responde por dívida anterior até dois anos após a averbação de sua saída.", "Morte e saída voluntária não recebem exatamente o mesmo tratamento quanto às obrigações posteriores; a falta de averbação prolonga exposição nos casos indicados.", "Responsabilidade residual", "responsabilidade que permanece por certo período após o fim do vínculo societário"),
    "1033": row("A sociedade dissolve-se pelo fim do prazo sem prorrogação tácita, consenso unânime, maioria absoluta em sociedade sem prazo ou extinção da autorização para funcionar. O inciso IV e o parágrafo único estão revogados.", "A lei enumera fatos que encerram a fase normal da sociedade e abrem sua liquidação, preservando continuidade tácita quando cabível.", "Sociedade de prazo indeterminado é dissolvida por deliberação de mais da metade do capital.", "Não se deve aplicar os trechos revogados; vencimento do prazo pode resultar em prorrogação indeterminada se não houver oposição nem liquidação.", "Dissolução", "evento que encerra a atividade normal e conduz a sociedade à liquidação"),
    "1034": row("Qualquer sócio pode pedir dissolução judicial se a constituição da sociedade for anulada ou se o fim social estiver esgotado ou se tornar inexequível.", "Quando a base jurídica ou prática da sociedade desaparece, o Judiciário pode encerrar o vínculo a pedido de sócio.", "Objeto único foi definitivamente concluído e sócio requer a dissolução judicial.", "Dificuldade passageira não equivale necessariamente a inexequibilidade do fim social.", "Inexequibilidade", "impossibilidade prática ou jurídica de realizar o objetivo social"),
    "1035": row("O contrato pode estabelecer outras causas de dissolução, que serão verificadas judicialmente se houver contestação.", "A autonomia contratual amplia as hipóteses legais, mas conflito sobre sua ocorrência pode exigir decisão judicial.", "Contrato prevê dissolução pela perda de licença e um sócio contesta que isso ocorreu.", "A cláusula deve ser válida e a via judicial torna-se relevante quando os fatos ou efeitos são impugnados.", "Causa contratual de dissolução", "evento previsto pelos sócios para encerrar a sociedade"),
    "1036": row("Dissolvida a sociedade, administradores devem providenciar imediatamente a nomeação do liquidante e limitar-se a negócios inadiáveis; novas operações geram responsabilidade solidária e ilimitada. Sócio pode pedir liquidação judicial quando a dissolução ocorre de pleno direito.", "A gestão muda de finalidade: deixa de expandir negócios e passa a conservar e liquidar o patrimônio.", "Após dissolução, administrador apenas evita perda urgente e convoca escolha do liquidante.", "Operação nova não necessária expõe pessoalmente administradores; ato urgente de conservação é diferente.", "Liquidante", "pessoa encarregada de realizar ativos, pagar dívidas e encerrar a sociedade"),
    "1037": row("Perdida a autorização de funcionamento, o Ministério Público promove liquidação judicial se administradores não agirem em trinta dias ou sócio não a requerer. Se o MP não agir em quinze dias da comunicação, a autoridade nomeia interventor para requerer a medida e administrar até o liquidante.", "A norma cria sequência institucional para que sociedade sem autorização não permaneça sem encerramento responsável.", "Órgão revoga autorização, comunica o MP e, diante das omissões nos prazos, nomeia interventor.", "Os prazos têm fatos iniciais diferentes e a atuação subsidiária depende das omissões anteriores.", "Interventor", "pessoa nomeada pela autoridade para administrar temporariamente e requerer a liquidação"),
    "1038": row("Se o contrato não indicar liquidante, os sócios o elegem, podendo escolher terceiro. O eleito pode ser destituído pelos sócios a qualquer tempo; qualquer liquidante pode ser afastado judicialmente por justa causa. A liquidação segue o capítulo legal próprio.", "A escolha é flexível, mas a forma de destituição depende da origem ou da existência de justa causa.", "Sócios elegem contador externo como liquidante e depois deliberam sua substituição.", "Destituição judicial exige justa causa; o procedimento de liquidação deve observar as regras remetidas.", "Destituição", "retirada formal de alguém da função que exercia"),
    "1039": row("Somente pessoas físicas podem ser sócias da sociedade em nome coletivo, e todas respondem solidária e ilimitadamente pelas obrigações. Internamente, o contrato ou convenção unânime posterior pode repartir limites, sem prejudicar terceiros.", "O tipo baseia-se na responsabilidade pessoal ampla; ajustes internos organizam regresso, mas não reduzem a garantia externa.", "Credor cobra toda a dívida de qualquer sócio, que depois usa o limite interno contra os demais.", "Pessoa jurídica não pode integrar esse tipo, e cláusula interna não é oponível ao credor.", "Sociedade em nome coletivo", "tipo societário formado apenas por pessoas físicas com responsabilidade solidária e ilimitada"),
    "1040": row("A sociedade em nome coletivo segue as regras de seu capítulo e, nas lacunas, as normas da sociedade simples do capítulo anterior.", "As regras gerais da sociedade simples completam o regime especial quando forem compatíveis e não houver disciplina própria.", "Questão administrativa não tratada no capítulo especial é resolvida pela regra compatível da sociedade simples.", "A remissão é supletiva: norma específica da sociedade em nome coletivo prevalece.", "Regra supletiva", "norma usada para preencher lacuna deixada pelo regime principal"),
}


